import * as THREE from 'three';
export function createWorkGuide(scene){
 const positions=new Float32Array(90),geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3).setUsage(THREE.DynamicDrawUsage));const line=new THREE.Line(geometry,new THREE.LineBasicMaterial({color:'#e6b66b',transparent:true,opacity:.7}));line.frustumCulled=false;scene.add(line);
 const arrowGeometry=new THREE.BufferGeometry();arrowGeometry.setAttribute('position',new THREE.Float32BufferAttribute([-.25,0,-.18,.22,0,0,-.25,0,.18],3));const arrow=new THREE.Mesh(arrowGeometry,new THREE.MeshBasicMaterial({color:'#e6b66b',side:THREE.DoubleSide}));scene.add(arrow);
 return {apply(frame){const u=frame.units.find(u=>u.id===frame.activityUnit)||frame.units[frame.selected],r=frame.physical?.recovery,path=r?.unit===u?.id&&r.guide?.length?r.guide:u?.physical.guide||[];line.visible=arrow.visible=path.length>1;if(!line.visible)return;const point=r?.unit===u?.id&&r.guide?.length?r.pose:u.physical.pose,points=[[point.x,point.z],...path].slice(0,30);points.forEach(([x,z],i)=>{positions[i*3]=x;positions[i*3+1]=.275;positions[i*3+2]=z;});geometry.setDrawRange(0,points.length);geometry.attributes.position.needsUpdate=true;const i=Math.min(points.length-1,5),a=points[Math.max(0,i-1)],b=points[i],yaw=Math.atan2(b[1]-a[1],b[0]-a[0]);arrow.position.set(b[0],.29,b[1]);arrow.rotation.set(0,-yaw,0);}};
}
